    <div class="toast" id="toast" role="status" aria-live="polite"></div>
    <script>
        const products = [...document.querySelectorAll('.product')];
        const searchInput = document.getElementById('searchInput');
        let activeFilter = 'Semua';
        let cartCount = 0;
        let toastTimer;
        function applyFilters() {
            const query = searchInput.value.trim().toLocaleLowerCase('id');
            let visible = 0;
            products.forEach((product) => {
                const matchesQuery = product.dataset.search.includes(query);
                const matchesFilter = activeFilter === 'Semua' || product.dataset.category === activeFilter || product.dataset.tags.split(' ').includes(activeFilter);
                product.hidden = !(matchesQuery && matchesFilter);
                if (!product.hidden) visible++;
            });
            document.getElementById('emptyState').classList.toggle('show', visible === 0);
        }
        function showToast(message) {
            const toast = document.getElementById('toast');
            toast.textContent = message;
            toast.classList.add('show');
            clearTimeout(toastTimer);
            toastTimer = setTimeout(() => toast.classList.remove('show'), 2100);
        }
        searchInput.addEventListener('input', applyFilters);
        document.querySelectorAll('.filter').forEach((button) => button.addEventListener('click', () => {
            document.querySelectorAll('.filter').forEach((item) => item.classList.remove('active'));
            button.classList.add('active');
            activeFilter = button.dataset.filter;
            document.querySelectorAll('.category').forEach((item) => item.classList.remove('active'));
            if (activeFilter === 'Semua') searchInput.value = '';
            applyFilters();
        }));
        document.querySelectorAll('.category').forEach((button) => button.addEventListener('click', () => {
            document.querySelectorAll('.category').forEach((item) => item.classList.remove('active'));
            button.classList.add('active');
            document.querySelectorAll('.filter').forEach((item) => item.classList.remove('active'));
            activeFilter = button.dataset.category;
            document.querySelector(`.filter[data-filter="${activeFilter}"]`)?.classList.add('active');
            applyFilters();
            document.getElementById('karya').scrollIntoView({behavior:'smooth'});
        }));
    </script>
